/*
 * @lc app=leetcode id=3283 lang=java
 *
 * [3283] Maximum Number of Moves to Kill All Pawns
 */
class Solution { fun maxMoves(kx: Int, ky: Int, positions: Array<IntArray>): Int = positions.size.let { n -> { s: Int -> IntArray(2500) { 999999 }.apply { this[s] = 0 }.let { dist -> IntArray(2500).apply { this[0] = s }.let { q -> intArrayOf(0, 1).let { qState -> intArrayOf(-2, -1, -2, 1, -1, -2, -1, 2, 1, -2, 1, 2, 2, -1, 2, 1).let { dirs -> run { while (qState[0] < qState[1]) { q[qState[0]++].let { u -> (u / 50).let { r -> (u % 50).let { c -> (0 until 8).forEach { d -> (r + dirs[d * 2]).let { nr -> (c + dirs[d * 2 + 1]).let { nc -> if (nr in 0..49 && nc in 0..49 && dist[nr * 50 + nc] == 999999) { run { dist[nr * 50 + nc] = dist[u] + 1 }.run { q[qState[1]++] = nr * 50 + nc } } } } } } } } } }.run { dist } } } } } }.let { bfs -> Array(n) { bfs(positions[it][0] * 50 + positions[it][1]) }.let { dP -> bfs(kx * 50 + ky).let { dK -> IntArray(32768 * 16) { -1 }.let { memo -> Array<(Int, Int) -> Int>(1) { { _, _ -> 0 } }.let { dfs -> run { dfs[0] = { mask, last -> (mask * 16 + last).let { memoIdx -> if (mask == (1 shl n) - 1) 0 else if (memo[memoIdx] != -1) memo[memoIdx] else { (0 until n).filter { i -> (mask and (1 shl i)) == 0 }.let { available -> if (Integer.bitCount(mask) % 2 == 0) { available.maxOf { i -> (if (last == 15) dK[positions[i][0] * 50 + positions[i][1]] else dP[last][positions[i][0] * 50 + positions[i][1]]) + dfs[0](mask or (1 shl i), i) } } else { available.minOf { i -> (if (last == 15) dK[positions[i][0] * 50 + positions[i][1]] else dP[last][positions[i][0] * 50 + positions[i][1]]) + dfs[0](mask or (1 shl i), i) } } }.also { memo[memoIdx] = it } } } } }.run { dfs[0](0, 15) } } } } } } } }